import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p68_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor linear_min_sub_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    double constant);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("linear_min_sub", &linear_min_sub_cuda, "Linear + min + subtract (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

// Singleton cuBLAS handle
static cublasHandle_t g_cublas_handle = nullptr;

static cublasHandle_t get_cublas_handle() {
    if (g_cublas_handle == nullptr) {
        cublasCreate(&g_cublas_handle);
    }
    return g_cublas_handle;
}

// Fused epilogue: out[i] += bias[col], then min(out[i], c) - c
// Uses float4 for vectorized access when N is divisible by 4
__global__ void fused_bias_min_sub_kernel(
    float* __restrict__ out,
    const float* __restrict__ bias,
    float constant,
    int M, int N)
{
    int total = M * N;
    int vec_total = total / 4;
    float4* out4 = reinterpret_cast<float4*>(out);

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < vec_total; i += stride) {
        int base = i * 4;
        float4 v = out4[i];
        int col0 = base % N;
        int col1 = (base + 1) % N;
        int col2 = (base + 2) % N;
        int col3 = (base + 3) % N;
        v.x = fminf(v.x + bias[col0], constant) - constant;
        v.y = fminf(v.y + bias[col1], constant) - constant;
        v.z = fminf(v.z + bias[col2], constant) - constant;
        v.w = fminf(v.w + bias[col3], constant) - constant;
        out4[i] = v;
    }

    // Handle remainder
    for (int i = idx + vec_total * 4; i < total; i += stride) {
        int col = i % N;
        out[i] = fminf(out[i] + bias[col], constant) - constant;
    }
}

// Optimized version when N is divisible by 4 and cols are aligned within float4
__global__ void fused_bias_min_sub_aligned_kernel(
    float* __restrict__ out,
    const float* __restrict__ bias,
    float constant,
    int M, int N)
{
    // Each thread handles 4 consecutive columns in a row
    // N must be divisible by 4
    int total_vec = M * (N / 4);
    float4* out4 = reinterpret_cast<float4*>(out);
    const float4* bias4 = reinterpret_cast<const float4*>(bias);

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < total_vec; i += stride) {
        int col_vec = i % (N / 4);
        float4 v = out4[i];
        float4 b = bias4[col_vec];
        v.x = fminf(v.x + b.x, constant) - constant;
        v.y = fminf(v.y + b.y, constant) - constant;
        v.z = fminf(v.z + b.z, constant) - constant;
        v.w = fminf(v.w + b.w, constant) - constant;
        out4[i] = v;
    }
}

torch::Tensor linear_min_sub_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    double constant)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");

    int M = input.size(0);
    int K = input.size(1);
    int N = weight.size(0); // out_features; weight is [out_features, in_features]

    auto output = torch::empty({M, N}, input.options());

    cublasHandle_t handle = get_cublas_handle();
    // Bind to current CUDA stream
    cublasSetStream(handle, at::cuda::getCurrentCUDAStream());

    // cuBLAS is column-major. We compute: output = input * weight^T
    // In column-major: output^T = weight * input^T
    // So: C = alpha * A * B^T + beta * C
    // With col-major interpretation:
    //   C(N x M) = weight(N x K) * input^T(K x M)
    // cublasGemmEx args (col-major):
    //   transa=N -> A is not transposed: A is weight [N x K] stored as col-major
    //   transb=T -> B is transposed: B is input [M x K], transposed to [K x M]
    //   m=N, n=M, k=K
    //   lda=N (leading dim of A = N, col-major [N x K])
    //   ldb=K (leading dim of B = K, col-major [M x K], but we're reading row-major input as col-major [K x M])
    //   ldc=N
    float alpha = 1.0f, beta = 0.0f;
    cublasGemmEx(
        handle,
        CUBLAS_OP_T,  // weight: row-major [N x K] treated as col-major [K x N], transposed -> [N x K] in col-major op
        CUBLAS_OP_N,  // input: row-major [M x K] treated as col-major [K x M]
        N, M, K,
        &alpha,
        weight.data_ptr<float>(), CUDA_R_32F, K,  // lda=K since weight is row-major [N x K]
        input.data_ptr<float>(),  CUDA_R_32F, K,  // ldb=K since input is row-major [M x K]
        &beta,
        output.data_ptr<float>(), CUDA_R_32F, N,  // ldc=N
        CUBLAS_COMPUTE_32F_FAST_TF32,
        CUBLAS_GEMM_DEFAULT_TENSOR_OP
    );

    // Fused epilogue: bias add + min + subtract
    float c = (float)constant;
    int total = M * N;
    int block = 256;

    if (N % 4 == 0) {
        int vec_total = M * (N / 4);
        int grid = (vec_total + block - 1) / block;
        grid = min(grid, 65535);
        fused_bias_min_sub_aligned_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
            output.data_ptr<float>(),
            bias.data_ptr<float>(),
            c, M, N
        );
    } else {
        int grid = (total / 4 + block - 1) / block;
        grid = min(grid, 65535);
        fused_bias_min_sub_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
            output.data_ptr<float>(),
            bias.data_ptr<float>(),
            c, M, N
        );
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a matrix multiplication, applies minimum, and subtracts a constant.
        """
    def __init__(self, in_features, out_features, constant):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.linear = nn.Linear(in_features, out_features)
        self.constant = nn.Parameter(torch.tensor(constant))
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        _use_fast = (
            x.is_cuda and
            x.dtype == torch.float32 and
            x.is_contiguous() and
            self.linear.weight.is_cuda and
            self.linear.weight.dtype == torch.float32 and
            self.linear.weight.is_contiguous() and
            self.linear.bias is not None and
            self.linear.bias.is_cuda and
            self.linear.bias.is_contiguous()
        )
        if _use_fast:
            x = _stark_get_extension().linear_min_sub(
                x,
                self.linear.weight,
                self.linear.bias,
                float(self.constant.detach().cpu())
            )
        else:
            x = self.linear(x)
            x = torch.min(x, self.constant)
            x = x - self.constant
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if not _use_fast:
            x = torch.min(x, self.constant)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if not _use_fast:
            x = x - self.constant
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        return x
        # <<<END_IMPROVE>>>

